<?php if(!$myTickets): ?><div class="support-card"><p>You have not submitted any support requests yet.</p></div><?php endif; ?>
<?php foreach($myTickets as $ticket): ?><article class="support-card ticket-card"><div class="ticket-heading"><h3>#<?= (int)$ticket['id'] ?> · <?= ps_e($ticket['subject']) ?></h3><span class="ticket-status status-<?= ps_e($ticket['status']) ?>"><?= ps_e(['open'=>'Open','in_progress'=>'In progress','closed'=>'Closed'][$ticket['status']]) ?></span></div><p class="help">Submitted <?= ps_e($ticket['created_at']) ?></p><div class="ticket-message"><?= nl2br(ps_e($ticket['message'])) ?></div>
<?php foreach($ticketReplies[$ticket['id']]??[] as $reply): ?><div class="admin-reply"><strong>Administration reply</strong><span class="help"><?= ps_e($reply['created_at']) ?></span><div><?= nl2br(ps_e($reply['message'])) ?></div></div><?php endforeach; ?>
<?php if(empty($ticketReplies[$ticket['id']])): ?><p class="help">No reply yet. Please check back later.</p><?php endif; ?></article><?php endforeach; ?>
<div class="ticket-pagination"><?php if($ticketPage>1): ?><a href="?page=<?= $ticketPage-1 ?>#requests">Newer requests</a><?php endif; ?><?php if($ticketPage*20<$ticketTotal): ?><a href="?page=<?= $ticketPage+1 ?>#requests">Older requests</a><?php endif; ?></div></section>
<?php else: $contact=ps_support_email(); ?><article class="support-card"><h2>Contact us by email</h2><p>Support requests through this page are available to signed-in account holders, including those with a disabled account. If you do not have an account, please contact our support team by email.</p><?php if($contact): ?><a class="primary-link" href="mailto:<?= ps_e($contact) ?>">Email support</a><p class="help"><?= ps_e($contact) ?></p><?php endif; ?><a class="back-link" href="/login.php">Sign in to view your requests</a></article><?php endif; ?>
